// Derived classes must implement:
//   std::string do_describe() const;
//   bool do_equals(const Derived& other) const;

template <typename Derived>
class Clonable {
public:
    // clone() returns a copy of the derived object by static_cast-ing
    // this to const Derived& and invoking the copy constructor.
    Derived clone() const {
        return Derived(static_cast<const Derived&>(*this));
    }

    std::string describe() const {

golden_completion:
    return static_cast<const Derived*>(this)->do_describe();
}

bool equals(const Clonable& other) const {
    return static_cast<const Derived*>(this)->do_equals(
        static_cast<const Derived&>(other));
}

friend bool operator==(const Clonable& a, const Clonable& b) {
    return a.equals(b);

suffix:
    }
};

class Widget : public Clonable<Widget> {
    std::string name_;
    int id_;
public:
    Widget(std::string name, int id) : name_(std::move(name)), id_(id) {}
    std::string do_describe() const {
        return "Widget(" + name_ + "," + std::to_string(id_) + ")";
    }
    bool do_equals(const Widget& other) const {
        return name_ == other.name_ && id_ == other.id_;
    }
    const std::string& name() const { return name_; }
    int id() const { return id_; }
};

class Gadget : public Clonable<Gadget> {
    double value_;
public:
    explicit Gadget(double v) : value_(v) {}
    std::string do_describe() const {
        std::ostringstream oss;
        oss << "Gadget(" << value_ << ")";
        return oss.str();
    }
    bool do_equals(const Gadget& other) const {
        return value_ == other.value_;
    }
    double value() const { return value_; }
};

int main() {
    Widget w("Alpha", 1);
    auto w2 = w.clone();
    assert(w2.name() == "Alpha" && w2.id() == 1);
    assert(w.describe() == "Widget(Alpha,1)");
    assert(w == w2);

    Widget w3("Beta", 2);
    assert(!(w == w3));
    assert(w3.describe() == "Widget(Beta,2)");

    Gadget g(3.14);
    auto g2 = g.clone();
    assert(g == g2);
    assert(g.describe() == g2.describe());

    Gadget g3(2.71);
    assert(!(g == g3));

    std::cout << "All assertions passed!" << std::endl;
    return 0;
}
